/* NHISA: buildless, accessible, responsive site. All interactions stay local.
   DESIGN_VARIANCE 5 / MOTION_INTENSITY 3 / VISUAL_DENSITY 4.
   The supplied SU Slate design system is the brand source of truth. */
(() => {
  'use strict';
  const $ = (selector, scope = document) => scope.querySelector(selector);
  const main = $('#main');
  const data = window.NHISA;
  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  const icon = (name, extra = '') => `<img class="icon ${extra}" src="assets/icons/${name}.svg" alt="" aria-hidden="true" />`;
  const arrow = '<span aria-hidden="true">↗</span>';
  const right = '<span aria-hidden="true">→</span>';
  function readStorage(key, fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
  function writeStorage(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { return false; } }
  let saved = readStorage('nhisa-saved', []);
  let tasks = readStorage('nhisa-tasks', {});
  if (!Array.isArray(saved)) saved = [];
  if (!tasks || typeof tasks !== 'object' || Array.isArray(tasks)) tasks = {};
  let filter = 'All resources';
  let query = '';
  let toastTimer;
  function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('visible'), 3000); }
  function resourceCard(resource) {
    const isSaved = saved.includes(resource.id);
    return `<article class="resource-card"><div class="resource-card-top">${icon(resource.icon, 'icon-orange')}<button class="bookmark-button" data-save="${resource.id}" aria-label="${isSaved ? 'Unsave' : 'Save'} ${escape(resource.name)}" aria-pressed="${isSaved}">${icon('bookmark', 'icon-small')}</button></div><span class="resource-category">${escape(resource.category)}</span><h3>${escape(resource.name)}</h3><p>${escape(resource.description)}</p><div class="resource-source">${escape(resource.source)}</div><a class="text-link" href="${escape(resource.url)}" target="_blank" rel="noopener noreferrer">Explore resource ${arrow}</a></article>`;
  }
  function cta(title = 'Your next chapter is a shared one.', text = 'Bring your perspective. Find your people. Help shape a community that grows with you.') {
    return `<section class="container cta-section"><div class="cta-box"><div><h2>${title}</h2><p>${text}</p></div><a class="button" href="#/join">Find your place ${arrow}</a></div></section>`;
  }
  function pageIntro(label, title, description, extra = '') { return `<section class="page-intro"><div class="container"><div class="breadcrumb"><a href="#/">Home</a><span aria-hidden="true">/</span><span>${label}</span></div><h1>${title}</h1><p>${description}</p>${extra}</div></section>`; }
  const home = () => `
    <div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">Newhouse International Student Association</div><h1>A new place.<span class="serif">A shared future.</span></h1><p class="hero-description">Find your people, navigate your career, and turn your international perspective into your next possibility.</p><div class="hero-actions"><a class="button" href="#/support">Find your next step ${right}</a><a class="text-link" href="#/about">Meet your community ${arrow}</a></div></div><figure class="hero-visual"><img class="hero-photo" src="assets/hero.webp" alt="Students sharing a conversation on Syracuse University's campus" width="800" height="580" fetchpriority="high" /><figcaption class="hero-image-footer"><div><p>Different journeys. Shared ambition.</p><span>Rooted in Newhouse. Connected to the world.</span></div>${icon('globe')}</figcaption></figure></section></div>
    <div class="quicknav-band"><nav class="container quicknav" aria-label="Explore our three pathways"><a href="#/support">${icon('book-open','icon-orange')}<span><strong>International student support</strong><small>Start with a little guidance.</small></span><span class="quick-arrow" aria-hidden="true">↗</span></a><a href="#/alumni">${icon('coffee','icon-orange')}<span><strong>Alumni connections</strong><small>One conversation can open a door.</small></span><span class="quick-arrow" aria-hidden="true">↗</span></a><a href="#/careers">${icon('suitcase','icon-orange')}<span><strong>Career access</strong><small>Make your next move with purpose.</small></span><span class="quick-arrow" aria-hidden="true">↗</span></a></nav></div>
    <section class="container section"><div class="section-header"><div class="eyebrow">Made for your journey</div><h2>Big questions.<br />A place to start.</h2><p>Wherever you are in your Newhouse journey, you do not have to figure out the next step alone.</p></div><div class="pathways">
      <article class="path-card"><div class="path-card-visual"><div class="steps-visual" aria-hidden="true"><div class="mini-step"><span class="num">01</span><span class="small-line"></span>Tell your story</div><div class="mini-step"><span class="num">02</span><span class="small-line"></span>Build your network</div><div class="mini-step"><span class="num">03</span><span class="small-line"></span>Take the next step</div></div></div><div class="path-card-body"><span class="path-card-label">International student support</span><h3>Find your footing.</h3><p>From your first LinkedIn profile to your next interview, find practical resources at every step.</p><a class="text-link" href="#/support">Explore the roadmap ${arrow}</a></div></article>
      <article class="path-card"><div class="path-card-visual"><img src="assets/conversation.webp" alt="Two students in conversation on a sunny campus" width="650" height="400" loading="lazy" /></div><div class="path-card-body"><span class="path-card-label">Alumni connections</span><h3>People, not just profiles.</h3><p>Discover the stories, honest advice, and conversations that can help you see what comes next.</p><a class="text-link" href="#/alumni">Explore the connections ${arrow}</a></div></article>
      <article class="path-card"><div class="path-card-visual"><div class="library-visual" aria-hidden="true"><div class="mini-resource"><div class="mini-resource-top">${icon('suitcase','icon-orange')}<span>↗</span></div><strong>Your next opportunity</strong><p>Resources worth keeping close.</p><div class="mini-resource-line"></div><div class="mini-resource-line short"></div></div></div></div><div class="path-card-body"><span class="path-card-label">Career access</span><h3>A clearer way forward.</h3><p>Spend less time searching for where to start. Explore useful platforms, tools, and career support.</p><a class="text-link" href="#/careers">Browse the resource library ${arrow}</a></div></article>
    </div></section>
    <section class="community-section section"><div class="container community-layout"><img src="assets/community.webp" alt="A group of students walking together outside the Schine Student Center" width="800" height="600" loading="lazy" /><div class="intro-text"><div class="eyebrow">Many backgrounds. Common ground.</div><h2>A community that<br />gets the journey.</h2><p>A new country. A different career landscape. Plenty of questions. NHISA brings Newhouse international students and alumni closer to the resources, perspectives, and people that make a difference.</p><div class="values-line"><span>${icon('globe')}Global perspectives</span><span>${icon('group')}Shared experience</span></div><a class="text-link" href="#/about">Get to know us ${arrow}</a></div></div></section>
    <section class="container section"><div class="section-header section-header-row"><div><h2>A few good places to begin.</h2><p>Useful resources for the next thing on your list.</p></div><a href="#/careers" class="text-link">View all resources ${arrow}</a></div><div class="resource-feature-grid">${data.resources.filter(r => r.featured).map(resourceCard).join('')}</div></section>
    ${cta()}`;
  function support() {
    return `${pageIntro('Student support', 'One step closer.<br /><span class="serif">A little more confident.</span>', 'A practical starting point for your career journey, from introducing yourself online to preparing for the conversation that comes next.')}<div class="container support-layout"><aside class="step-sidebar" aria-label="Career roadmap"><h2>Your career roadmap</h2>${data.steps.map((step,i) => `<a class="step-link" href="#/support?step=${step.id}" ${i===0?'aria-current="step"':''}><span>0${i+1}</span><span>${step.short}</span></a>`).join('')}<p class="progress-caption" id="task-progress">${taskProgress()}</p><p class="support-overview">Your checklist is saved in this browser. Move through the steps at your own pace.</p></aside><div>${data.steps.map((step,i) => `<section class="step-content" id="step-${step.id}"><div class="step-heading"><span class="step-num">0${i+1}</span><h2>${step.name}</h2></div><p>${step.intro}</p><div class="task-list">${step.tasks.map((task,j) => `<label class="task-label"><input type="checkbox" data-task="${step.id}-${j}" ${tasks[`${step.id}-${j}`]?'checked':''} /><span>${escape(task)}</span></label>`).join('')}</div><div class="step-resources">${step.resources.map(id => { const resource = data.resources.find(r => r.id === id); return `<a class="resource-chip" href="${resource.url}" target="_blank" rel="noopener noreferrer">${resource.name} ${arrow}</a>`; }).join('')}</div></section>`).join('')}</div></div>${cta('Every next step is easier together.', 'A question, a new perspective, or a conversation. There is a place for you in this community.')}`;
  }
  function taskProgress() { return `${data.steps.reduce((sum,step) => sum + step.tasks.filter((_,i) => tasks[`${step.id}-${i}`]).length, 0)} of ${data.steps.reduce((sum,step) => sum + step.tasks.length,0)} steps checked`; }
  function careers(params) {
    filter = params.get('filter') === 'saved' ? 'Saved' : 'All resources'; query = '';
    return `${pageIntro('Career access', 'Less searching.<br /><span class="serif">More moving forward.</span>', 'Keep useful career resources in one place. Explore university support, professional platforms, and tools for your next application.', `<form id="resource-search" class="search-bar" role="search"><label class="search-field">${icon('magnifying-glass','icon-small')}<input id="resource-query" type="search" aria-label="Search resources" placeholder="Search resources, tools, or topics…" autocomplete="off" /></label><button class="button" type="submit">Search <span aria-hidden="true">→</span></button></form>`)}<section class="container" aria-label="Resource library"><div class="filter-bar"><div class="filter-chips" aria-label="Filter resources">${['All resources','Career advising','Job platforms','Networking','Application tools','International students','Saved'].map(name => `<button class="filter-chip" data-filter="${name}" aria-pressed="${filter===name}">${name==='Saved'?'Saved resources':name}</button>`).join('')}</div><p class="result-count" id="result-count" aria-live="polite"></p></div><div class="library-grid" id="library-results">${libraryResults()}</div><p class="resource-notice">This is a resource directory. Resources open on their original websites and may require a university sign-in. Alumni-shared opportunities will be added as the community grows.</p></section>${cta('Know a resource that helped you?', 'Good advice travels further when we share it. Help us make the next student’s starting point a little clearer.')}`;
  }
  function filteredResources() { return data.resources.filter(resource => (filter==='All resources'||(filter==='Saved'?saved.includes(resource.id):resource.category===filter)) && `${resource.name} ${resource.description} ${resource.category} ${resource.source}`.toLowerCase().includes(query.toLowerCase())); }
  function libraryResults() {
    const results = filteredResources();
    if (results.length) return results.map(resourceCard).join('');
    return `<div class="empty-state">${icon(filter==='Saved'?'bookmark':'magnifying-glass','icon-orange')}<h2>${filter==='Saved'?'Keep your good finds here.':'A different search might help.'}</h2><p>${filter==='Saved'?'Use the bookmark button on any resource to save it in this browser.':'No resources match these filters. Try a broader topic or clear your search.'}</p><button class="button button-outline" id="reset-filters">Explore all resources ${right}</button></div>`;
  }
  function updateLibrary() { $('#library-results').innerHTML = libraryResults(); $('#result-count').textContent = `${filteredResources().length} resource${filteredResources().length===1?'':'s'}`; document.querySelectorAll('[data-filter]').forEach(button => button.setAttribute('aria-pressed', button.dataset.filter===filter)); }
  const storyThemes = [
    {id:'first-steps', category:'Career beginnings',title:'The first step is rarely a straight line.',description:'The conversations we are building: first roles, lessons learned, and finding your direction.',image:'journey',alt:'Students talking together on the Syracuse campus'},
    {id:'coffee-chats',category:'Conversations and connections',title:'A coffee. A question. A new perspective.',description:'A space for honest conversations with Newhouse alumni and communications professionals.',image:'courtyard',alt:'Students gathered at an outdoor table beneath an orange umbrella'},
    {id:'shared-stories',category:'Life beyond Newhouse',title:'Different paths. A familiar starting point.',description:'Stories about taking a Newhouse experience into the working world, wherever that leads.',image:'students',alt:'Students walking together outside a Syracuse University building'}
  ];
  function alumni() {
    const published = data.alumni.filter(person => person.published);
    return `${pageIntro('Alumni connections', 'A connection can<br /><span class="serif">change your perspective.</span>', 'Behind every career path is a person, a few turning points, and something worth sharing. This is where those conversations will live.')}<section class="container alumni-lead"><div class="section-header"><div class="eyebrow">The conversations ahead</div><h2>People, paths, and possibilities.</h2><p>Our first alumni conversations are being prepared. Explore the themes, or help start the next conversation.</p></div><div class="story-grid">${published.length?published.map(person => `<article class="story-card"><img src="${escape(person.photo)}" alt="${escape(person.name)}" loading="lazy" /><div><small>${escape(person.field)}</small><h2>${escape(person.name)}</h2><p>${escape(person.intro)}</p><a class="text-link" href="#/alumni/profile/${encodeURIComponent(person.id)}">Read the conversation ${arrow}</a></div></article>`).join(''):storyThemes.map(story => `<article class="story-card"><img src="assets/${story.image}.webp" alt="${story.alt}" loading="lazy" width="600" height="700" /><div><small>${story.category}</small><h2>${story.title}</h2><p>${story.description}</p><a class="text-link" href="#/alumni/${story.id}">About this series ${arrow}</a></div></article>`).join('')}</div></section>${cta('Your experience could be someone’s starting point.', 'Newhouse alumni and industry professionals: share a little of your journey and help the next generation find their way.')}`;
  }
  function storyPage(id) {
    const story = storyThemes.find(item => item.id===id);
    if (!story) return notFound();
    return `${pageIntro('Alumni connections', story.title, story.description)}<div class="container detail-layout"><img src="assets/${story.image}.webp" alt="${story.alt}" width="700" height="800" /><div><div class="eyebrow">${story.category}</div><h2>A space for the stories that help us grow.</h2><p>This conversation series is coming soon. We are building a collection of real experiences from Newhouse alumni and communications professionals.</p><p>Each published conversation will bring together a person’s background, their time at Newhouse, career turning points, and advice they would share with international students.</p><details><summary>What will these conversations explore?</summary><p>How a career begins, the lessons behind a first role, useful resources, building connections, and the perspectives that travel with you from Newhouse.</p></details><a class="button" href="#/join?role=alumni">Share your experience ${arrow}</a><p style="margin-top:20px"><a class="text-link" href="#/alumni">${icon('arrow-left','icon-small')} Back to alumni connections</a></p></div></div>`;
  }
  function profilePage(id) {
    const person = data.alumni.find(person => person.id===id&&person.published);
    if (!person) return notFound();
    return `${pageIntro('Alumni connections',escape(person.name),escape(person.intro))}<article class="container detail-layout"><img src="${escape(person.photo)}" alt="${escape(person.name)}" /><div><div class="eyebrow">${escape(person.field)}</div><h2>${escape(person.role)}</h2><p>${escape(person.background)}</p>${(person.questions||[]).map(item => `<h3>${escape(item.question)}</h3><p>${escape(item.answer)}</p>`).join('')}<a class="text-link" href="#/alumni">Back to alumni connections ${right}</a></div></article>`;
  }
  function about() {
    return `${pageIntro('About NHISA','New perspectives.<br /><span class="serif">Common ground.</span>','A professional community and career resource hub created around the experience of Newhouse international students.')}<section class="container section"><div class="editorial-intro"><img src="assets/campus.webp" alt="The Newhouse communications center on Syracuse University's campus" width="800" height="800" /><div><h2>Make the journey<br />a little more connected.</h2><p>Finding your way in a new place comes with questions. Where do I start my career search? How do I meet people in my industry? What can I learn from someone who has been here before?</p><p>NHISA brings useful resources, alumni experiences, and career starting points into one place, with a focus on Newhouse international students.</p><a class="text-link" href="#/join">Be part of the community ${arrow}</a></div></div><div class="about-values"><div>${icon('book-open','icon-orange')}<h3>Practical support.</h3><p>Clear starting points for LinkedIn, applications, networking, and interview preparation.</p></div><div>${icon('group','icon-orange')}<h3>Human connections.</h3><p>A space to learn from alumni and professionals through thoughtful conversations and shared experience.</p></div><div>${icon('globe','icon-orange')}<h3>Global perspectives.</h3><p>A community that recognizes the experience international students bring to communications and beyond.</p></div></div></section>${cta()}`;
  }
  function join(params) {
    const draft = readStorage('nhisa-interest-draft', {});
    const safeDraft = draft&&typeof draft==='object'&&!Array.isArray(draft)?draft:{};
    const selectedRole = params.get('role')==='alumni'?'Alumni or industry professional':safeDraft.role||'Current student';
    return `${pageIntro('Get involved','Your perspective<br /><span class="serif">belongs here.</span>','Whether you are finding your footing or sharing what you have learned, there is a place for you in this community.')}<div class="container join-layout"><aside class="join-aside"><img src="assets/orange-campus.webp" alt="A diverse group of students walking together across Syracuse University's campus" width="700" height="500" /><h2>Start with a hello.</h2><p>Students can find support and new perspectives. Alumni and professionals can help by sharing their experiences, resources, or interest in a future coffee chat.</p></aside><div class="form-card" id="interest-card"><h2>A little about you.</h2><p>Prepare a short introduction to share with the NHISA team.</p><form id="interest-form"><div class="form-field"><label for="interest-name">Your name <span aria-hidden="true">*</span></label><input id="interest-name" name="name" autocomplete="name" required maxlength="100" value="${escape(safeDraft.name||'')}" /></div><div class="form-field"><label for="interest-email">Email address <span aria-hidden="true">*</span></label><input id="interest-email" name="email" type="email" autocomplete="email" required maxlength="200" placeholder="you@syr.edu" value="${escape(safeDraft.email||'')}" /></div><div class="form-field"><label for="interest-role">I am a…</label><select id="interest-role" name="role">${['Current student','Alumni or industry professional','Prospective student','Community supporter'].map(role=>`<option ${selectedRole===role?'selected':''}>${role}</option>`).join('')}</select></div><div class="form-field"><label for="interest-message">What brings you here? <span style="font-weight:400">(optional)</span></label><textarea id="interest-message" name="message" maxlength="2000" placeholder="A question, an idea, or something you would like to share…">${escape(safeDraft.message||'')}</textarea></div><button class="button" type="submit">Prepare my introduction ${right}</button><p class="form-note">This form creates a draft on your device. It does not send your details or register membership. You can copy or download your introduction to share with the NHISA team.</p></form></div></div>`;
  }
  function privacy() {
    return `${pageIntro('Privacy and accessibility','A thoughtful space.<br /><span class="serif">A clear experience.</span>','How this website handles your information and supports access.')}<article class="container privacy-content"><h2>Your information stays with you.</h2><p>This version of the NHISA website does not create accounts, send form submissions, or use analytics trackers. Bookmarks, checklist progress, and introductions you choose to save are stored in your browser on this device.</p><p>Introductions are prepared locally. You decide whether to copy, download, or share them. Clearing your browser’s site data removes saved resources, progress, and introduction drafts.</p><h2>Resources open on other websites.</h2><p>External links take you to the resource provider’s website. Those websites have their own privacy practices and may require university access. No sign-in credentials are collected by this website.</p><h2>Built for access.</h2><p>This site includes keyboard navigation, visible focus indicators, descriptive image text, clear form labels, and reduced-motion support. It adapts to small screens and text zoom.</p><button class="button button-outline" id="clear-local-data">Clear my saved data</button><p id="privacy-clear-status" role="status" style="margin-top:20px"></p></article>`;
  }
  function notFound() { return `<section class="container section empty-state"><h1>This path is still taking shape.</h1><p>Let us bring you back to a good place to begin.</p><a class="button" href="#/">Back to home ${right}</a></section>`; }
  function route() {
    const hash = location.hash.slice(1)||'/';
    const [path, search=''] = hash.split('?');
    const params = new URLSearchParams(search);
    const section = path.split('/')[1]||'home';
    const pages = { home, support, careers:()=>careers(params), alumni, about, join:()=>join(params), privacy };
    let title = { home:'A new place. A shared future.',support:'International student support',careers:'Career access',alumni:'Alumni connections',about:'About our community',join:'Get involved',privacy:'Privacy and accessibility' }[section] || 'Find your next step';
    const segments = path.split('/').filter(Boolean);
    main.innerHTML = section==='alumni'&&segments[1] ? (segments[1]==='profile'?profilePage(decodeURIComponent(segments[2]||'')):storyPage(segments[1])) : (pages[section]||notFound)();
    document.title = `${title} | NHISA`;
    document.querySelectorAll('[data-nav]').forEach(link=>{ if(link.dataset.nav===section)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current'); });
    closeMenu();
    window.scrollTo({top:0,behavior:'instant'});
    if(section==='careers')updateLibrary();
    if(section==='support'&&params.has('step')){
      const step=data.steps.find(step=>step.id===params.get('step'));
      if(step){requestAnimationFrame(()=>$('#step-'+step.id).scrollIntoView({behavior:'instant',block:'start'}));document.querySelectorAll('.step-link').forEach(link=>{if(link.hash.endsWith('step='+step.id))link.setAttribute('aria-current','step');else link.removeAttribute('aria-current');});}
    }
    if(route.initialized)main.focus({preventScroll:true});
    route.initialized=true;
  }
  function closeMenu() { $('.primary-nav').classList.remove('open'); $('.menu-toggle').setAttribute('aria-expanded','false'); $('.menu-toggle').setAttribute('aria-label','Open navigation'); document.body.classList.remove('menu-open'); }
  $('.menu-toggle').addEventListener('click',()=>{ const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true'; $('.primary-nav').classList.toggle('open',open); $('.menu-toggle').setAttribute('aria-expanded',String(open)); $('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation'); document.body.classList.toggle('menu-open',open); });
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('.primary-nav').classList.contains('open')){closeMenu();$('.menu-toggle').focus();}});
  document.addEventListener('click',event=>{
    if(event.target.closest('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView({block:'start'});return;}
    const bookmark=event.target.closest('[data-save]');
    if(bookmark){const id=bookmark.dataset.save; const resource=data.resources.find(item=>item.id===id);if(!resource)return; const wasSaved=saved.includes(id);saved=wasSaved?saved.filter(item=>item!==id):[...saved,id]; const persisted=writeStorage('nhisa-saved',saved);document.querySelectorAll(`[data-save="${id}"]`).forEach(button=>{button.setAttribute('aria-pressed',String(!wasSaved));button.setAttribute('aria-label',`${wasSaved?'Save':'Unsave'} ${resource.name}`);});if($('#library-results')&&filter==='Saved')updateLibrary();toast(persisted?(wasSaved?'Resource removed from your saved list.':'Resource saved for later.'): 'Updated for this visit. Browser storage is unavailable.');}
    const filterButton=event.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;updateLibrary();}
    if(event.target.closest('#reset-filters')){filter='All resources';query='';$('#resource-query').value='';updateLibrary();}
    if(event.target.closest('#clear-local-data')){try{['nhisa-saved','nhisa-tasks','nhisa-interest-draft'].forEach(key=>localStorage.removeItem(key));saved=[];tasks={};$('#privacy-clear-status').textContent='Your saved resources, checklist progress, and introduction draft have been cleared.';}catch{$('#privacy-clear-status').textContent='Browser storage could not be accessed. Clear site data in your browser settings.';}}
    if(event.target.closest('#copy-introduction'))copyIntroduction();
    if(event.target.closest('#download-introduction'))downloadIntroduction();
  });
  document.addEventListener('input',event=>{if(event.target.id==='resource-query'){query=event.target.value.trim();updateLibrary();}});
  document.addEventListener('change',event=>{if(event.target.matches('[data-task]')){tasks[event.target.dataset.task]=event.target.checked;const persisted=writeStorage('nhisa-tasks',tasks);$('#task-progress').textContent=taskProgress();if(!persisted)toast('Progress is available for this visit. Browser storage is unavailable.');}});
  let introduction='';
  function introductionText(draft){return `Hello NHISA,\n\nMy name is ${draft.name}.\nI am a: ${draft.role}.\nEmail: ${draft.email}\n\n${draft.message||'I would like to learn more about the community and how to get involved.'}\n\nThank you,\n${draft.name}\n`;}
  document.addEventListener('submit',event=>{
    if(event.target.id==='resource-search'){event.preventDefault();query=$('#resource-query').value.trim();updateLibrary();}
    if(event.target.id==='interest-form'){event.preventDefault();const form=new FormData(event.target);const draft=Object.fromEntries(form);draft.name=String(draft.name).trim();draft.email=String(draft.email).trim();draft.message=String(draft.message).trim();if(!draft.name){$('#interest-name').setCustomValidity('Please enter your name.');$('#interest-name').reportValidity();$('#interest-name').addEventListener('input',()=>$('#interest-name').setCustomValidity(''),{once:true});return;}const persisted=writeStorage('nhisa-interest-draft',draft);introduction=introductionText(draft);$('#interest-card').innerHTML=`<div class="draft-success"><h2 tabindex="-1" id="draft-heading">Your introduction is ready.</h2><p>${persisted?'A draft is saved in this browser.':'Your draft is available for this visit.'} Nothing has been sent. Copy or download it to share directly with the NHISA team.</p><button class="button" id="copy-introduction">Copy introduction ${icon('envelope','icon-small')}</button><button class="button button-outline" id="download-introduction">Download introduction ${icon('download','icon-small')}</button><a class="text-link" href="#/join?edit=true">Edit my introduction ${right}</a></div>`;$('#draft-heading').focus();}
  });
  async function copyIntroduction(){try{if(!navigator.clipboard?.writeText)throw new Error('clipboard-unavailable');await navigator.clipboard.writeText(introduction);toast('Introduction copied. You can share it when you are ready.');}catch{toast('Copy is unavailable here. Download your introduction instead.');}}
  function downloadIntroduction(){const blob=new Blob([introduction],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='NHISA-introduction.txt';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your introduction is ready to download.');}
  window.addEventListener('hashchange',route);
  route();
})();
